47	    /**
48	     * Formats an owner's salutation, as required by the API's read-only {@code salutation}
49	     * field: the owner's title and last name separated by a single space (e.g. {@code 'DR Who'})
50	     * when a title is present, or just the last name when no title was supplied.
51	     *
52	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
53	     * applied only where referenced via {@code qualifiedByName}.
54	     */
55	    @Named("formatSalutation")
56	    default String formatSalutation(Owner owner) {
57	        if (owner == null) {
58	            return null;
59	        }
60	        String title = owner.getTitle();
61	        if (title == null || title.isEmpty()) {
62	            return owner.getLastName();
63	        }
64	        return title + " " + owner.getLastName();
65	    }
