98	    /**
99	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
100	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
101	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
102	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
103	     * telephone is present.
104	     *
105	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
106	     * applied only where referenced via {@code qualifiedByName}.
107	     */
108	    @Named("formatTelephoneDisplay")
109	    default String formatTelephoneDisplay(Owner owner) {
110	        if (owner == null) {
111	            return null;
112	        }
113	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
114	    }
