116	    /**
117	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
118	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
119	     * {@code YY} is the last two digits of the fiscal year (the fiscal year starting on
120	     * 1 July) of the business-day-adjusted registration date (e.g. {@code 'NSW-1A2B3C4D-M26'}),
121	     * as required by the API's read-only {@code membershipNumber} field. Returns {@code null}
122	     * when either the customer code or registration date is absent.
123	     *
124	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
125	     * applied only where referenced via {@code qualifiedByName}.
126	     */
127	    @Named("formatMembershipNumber")
128	    default String formatMembershipNumber(Owner owner) {
129	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
130	            return null;
131	        }
132	        return String.format("%s-M%02d", owner.getCustomerCode(),
133	            fiscalYearStart(owner.getRegistrationDate()) % 100);
134	    }
