136	    /**
137	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, as required by the API's read-only
138	     * {@code fiscalYear} field: the fiscal year of the business-day-adjusted registration date,
139	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the
140	     * calendar year in which that fiscal year begins (so a registration date of
141	     * {@code 2026-10-02} yields {@code 'FY26'} and {@code 2026-03-02} yields {@code 'FY25'}).
142	     * Returns {@code null} when no registration date is present.
143	     *
144	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
145	     * applied only where referenced via {@code qualifiedByName}.
146	     */
147	    @Named("formatFiscalYear")
148	    default String formatFiscalYear(Owner owner) {
149	        if (owner == null || owner.getRegistrationDate() == null) {
150	            return null;
151	        }
152	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
153	    }
154	
155	    /**
156	     * Returns the calendar year in which the fiscal year containing {@code date} begins. The
157	     * fiscal year starts on 1 July, so dates in July through December belong to the fiscal year
158	     * starting in their own calendar year, while dates in January through June belong to the
159	     * fiscal year that started in the previous calendar year.
160	     */
161	    private static int fiscalYearStart(LocalDate date) {
162	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
163	    }
164	
165	    /**
166	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
167	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
168	     * code. Returns {@code null} when the customer code is absent.
169	     *
170	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
171	     * applied only where referenced via {@code qualifiedByName}.
172	     */
173	    @Named("formatCheckDigit")
174	    default Integer formatCheckDigit(Owner owner) {
175	        if (owner == null || owner.getCustomerCode() == null) {
176	            return null;
177	        }
178	        return LuhnCheckDigit.compute(owner.getCustomerCode());
179	    }
180	
181	    /**
182	     * Computes an owner's membership points, as required by the API's read-only
183	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
184	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
185	     * of 3 or more members, plus 3 when the owner's tenure spans at least one elapsed fiscal year
186	     * (the registration date's fiscal year precedes the current fiscal year, the fiscal year
187	     * starting on 1 July).
188	     *
189	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
190	     * applied only where referenced via {@code qualifiedByName}.
191	     */
192	    @Named("formatMembershipPoints")
193	    default Integer formatMembershipPoints(Owner owner) {
194	        if (owner == null) {
195	            return null;
196	        }
197	        int points = 0;
198	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
199	            points += 2;
200	        }
201	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
202	            points += 1;
203	        }
204	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
205	            points += 2;
206	        }
207	        if (owner.getRegistrationDate() != null
208	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
209	            points += 3;
210	        }
211	        return points;
212	    }
213	
214	    /**
215	     * Derives an owner's membership level, as required by the API's read-only
216	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
217	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
218	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
219	     *
220	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
221	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
222	     * to record the membership level on the create audit line).
223	     */
224	    @Named("formatMembershipLevel")
225	    default Integer formatMembershipLevel(Owner owner) {
226	        if (owner == null) {
227	            return null;
228	        }
229	        int points = formatMembershipPoints(owner);
230	        if (points <= 1) {
231	            return 1;
232	        }
233	        if (points <= 3) {
234	            return 2;
235	        }
236	        if (points <= 5) {
237	            return 3;
238	        }
239	        return 4;
240	    }
241	
242	    /**
243	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
244	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
245	     * locality is read from the same region-and-hash identity that the customer code encodes.
246	     * When no customer code is present (e.g. an owner that predates the code), the region is
247	     * resolved directly from the postcode (falling back to the city-to-region table, else
248	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
249	     *
250	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
251	     * applied only where referenced via {@code qualifiedByName}.
252	     */
253	    @Named("formatLocality")
254	    default String formatLocality(Owner owner) {
255	        if (owner == null) {
256	            return null;
257	        }
258	        String customerCode = owner.getCustomerCode();
259	        if (customerCode != null) {
260	            int dash = customerCode.indexOf('-');
261	            if (dash > 0) {
262	                return customerCode.substring(0, dash);
263	            }
264	        }
265	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
266	    }
267	
268	    /**
269	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
270	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
271	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
272	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
273	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
274	     *
275	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
276	     * applied only where referenced via {@code qualifiedByName}.
277	     */
278	    @Named("formatTimezone")
279	    default String formatTimezone(Owner owner) {
280	        if (owner == null) {
281	            return null;
282	        }
283	        return LocalityResolver.timezone(formatLocality(owner));
284	    }
285	
286	    /**
287	     * Derives an owner's preferred contact channel, as required by the API's read-only
288	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
289	     * otherwise {@code 'PHONE'}.
290	     *
291	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
292	     * applied only where referenced via {@code qualifiedByName}.
293	     */
294	    @Named("formatContactPreference")
295	    default String formatContactPreference(Owner owner) {
296	        if (owner == null) {
297	            return null;
298	        }
299	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
300	    }
301	
302	    /**
303	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
304	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
305	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
306	     * no birth date was supplied (so the field is absent), or when no registration date is yet
307	     * known against which to compute the age.
308	     *
309	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
310	     * applied only where referenced via {@code qualifiedByName}.
311	     */
312	    @Named("formatAgeBand")
313	    default String formatAgeBand(Owner owner) {
314	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
315	            return null;
316	        }
317	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
318	        if (age < 18) {
319	            return "MINOR";
320	        }
321	        if (age < 65) {
322	            return "ADULT";
323	        }
324	        return "SENIOR";
325	    }
326	
327	    private static String initial(String name) {
328	        if (name == null || name.isEmpty()) {
329	            return "";
330	        }
331	        return Character.toUpperCase(name.charAt(0)) + ".";
332	    }
