346	    /**
347	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
348	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
349	     * title was supplied. This is the single place the inbound title conversion lives: it runs
350	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
351	     * update path, keeping both consistent.
352	     *
353	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
354	     * applied only where referenced via {@code qualifiedByName}.
355	     */
356	    @Named("mapTitle")
357	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
358	        return title == null ? null : title.getValue();
359	    }
