361	    /**
362	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
363	     * normalizing each. This is the single place the structured-field normalization rule lives: it
364	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
365	     * called directly on the update path to keep both create and update consistent.
366	     *
367	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
368	     * {@code address} is set to the {@link #composeAddress composed} effective address.
369	     */
370	    @AfterMapping
371	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
372	        if (ownerDto == null) {
373	            return;
374	        }
375	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
376	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
377	        owner.setAddress(composeAddress(ownerDto));
378	    }
379	
380	    /**
381	     * Composes the effective, normalized postal address for an owner from the supplied fields,
382	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
383	     * present, the result is the normalized {@code addressLine1} with the normalized
384	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
385	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
386	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
387	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
388	     */
389	    default String composeAddress(OwnerFieldsDto ownerDto) {
390	        if (ownerDto == null) {
391	            return null;
392	        }
393	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
394	        if (line1 != null && !line1.isEmpty()) {
395	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
396	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
397	        }
398	        return normalizeAddress(ownerDto.getAddress());
399	    }
400	
401	    /**
402	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
403	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
404	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
405	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
406	     * {@code '12 MAIN STREET'}.
407	     *
408	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
409	     * only where referenced via {@code qualifiedByName}.
410	     */
411	    @Named("normalizeAddress")
412	    default String normalizeAddress(String address) {
413	        return AddressNormalizer.normalize(address);
414	    }
415	
416	    /**
417	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
418	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
419	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
420	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
421	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
422	     *
423	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
424	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
425	     *
426	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
427	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
428	     */
429	    @Named("normalizeTelephone")
430	    default String normalizeTelephone(String telephone) {
431	        return TelephoneNormalizer.toE164(telephone);
432	    }
433	
434	    /**
435	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
436	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
437	     * guarantees any value present is a syntactically valid address.
438	     *
439	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
440	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
441	     * e.g. on update).
442	     */
443	    @Named("normalizeEmail")
444	    default String normalizeEmail(String email) {
445	        return email == null ? null : email.toLowerCase(Locale.ROOT);
446	    }
447	
448	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
449	
450	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
451	
452	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
453	        OwnerPageDto ownerPageDto = new OwnerPageDto();
454	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
455	        ownerPageDto.setPage(ownerPage.getNumber());
456	        ownerPageDto.setSize(ownerPage.getSize());
457	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
458	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
459	        return ownerPageDto;
460	    }
461	}
